<template><section aria-label="本任务已保存分析结果"><h3>查看本任务分析结果</h3><p>读取已保存的本机候选，不执行统计。候选结果尚未正式采用，不能据此声明研究完成。</p><p v-if="!reference?.runId">本任务尚无运行引用，请先在数据分析阶段核对。</p><button :disabled="busy||!reference?.runId" @click="load">读取已保存结果</button><p v-if="error" role="alert">{{error}}</p><p v-if="busy" role="status">正在读取</p><ul v-if="run"><li v-for="item in run.artifacts" :key="item.artifactId+item.versionId">{{item.name}} · 固定版本 {{item.versionId}}<button :disabled="busy" @click="preview(item)">查看结果</button><button :disabled="readOnly||busy||invalid.includes(item.artifactId+item.versionId)" @click="cite(item)">引用到报告草稿</button></li></ul><pre v-if="content">{{content}}</pre></section></template>
<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {sandboxClient,type SandboxRun,type SandboxArtifact} from '@/api/researchSandbox'
import type {SandboxReference} from '@/types/research-contracts'
import {resultIssue} from '@/utils/researchPreviewInput'
const props=defineProps<{taskId:string;reference:SandboxReference|null;readOnly?:boolean}>(),emit=defineEmits<{'cite':[value:string]}>(),run=ref<SandboxRun|null>(null),error=ref(''),content=ref(''),busy=ref(false),invalid=ref<string[]>([])
let generation=0
watch(()=>[props.taskId,props.reference?.workspaceId,props.reference?.runId],()=>{generation++;run.value=null;content.value='';error.value='';busy.value=false;invalid.value=[]})
onBeforeUnmount(()=>generation++)
function client(){const token=sessionStorage.getItem('research-sandbox-token');if(!token)throw Error('请先在数据分析阶段连接本机沙箱');return sandboxClient(token)}
async function load(){if(busy.value||!props.reference?.runId)return;const epoch=++generation,reference={...props.reference};busy.value=true;run.value=null;content.value='';error.value='';try{const value=await client().run(reference.runId!);if(epoch!==generation)return;const issue=resultIssue(reference,value);if(issue)throw Error(issue);run.value=value}catch(e){if(epoch===generation)error.value=e instanceof Error?e.message:'读取失败'}finally{if(epoch===generation)busy.value=false}}
async function preview(item:SandboxArtifact){const current=run.value;if(!current||busy.value)return;const epoch=generation;busy.value=true;content.value='';error.value='';try{if(item.size>4*1024*1024)throw Error('文件超过预览限制');if(!/\.(json|csv|txt)$/i.test(item.name))throw Error('此处仅支持文本结果预览');const blob=await client().download(current.runId,item);const text=await blob.text();if(epoch===generation){content.value=text;invalid.value=invalid.value.filter(x=>x!==item.artifactId+item.versionId)}}catch(e){if(epoch===generation){invalid.value=[...new Set([...invalid.value,item.artifactId+item.versionId])];error.value=e instanceof Error?e.message:'结果读取失败'}}finally{if(epoch===generation)busy.value=false}}
function cite(item:SandboxArtifact){if(invalid.value.includes(item.artifactId+item.versionId)||props.readOnly||!run.value||!props.reference||resultIssue(props.reference,run.value))return;emit('cite',JSON.stringify({taskId:props.taskId,workspaceId:run.value.workspaceId,runId:run.value.runId,inputFingerprint:run.value.inputFingerprint,artifactId:item.artifactId,versionId:item.versionId,sha256:item.sha256,name:item.name,status:'本机已保存候选，尚未正式采用'}))}
</script>
<style scoped>section{min-width:0;padding:12px;background:#f5f8f5}li,pre{overflow-wrap:anywhere;white-space:pre-wrap}button{font:inherit;padding:8px;margin:6px}pre{max-height:300px;overflow:auto}p[role=alert]{color:#9b392a}</style>
